% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source page 8 question 10a; teacher page 22"}
\begin{tikzpicture}[x=1cm,y=1cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-1.3,-4.2) rectangle (4.2,1.1);
\draw[->,line width=0.5pt] (-1.1,0)--(4,0) node[below,font=\fontsize{10}{12}\selectfont] {$x$};
\draw[->,line width=0.5pt] (0,-4)--(0,0.9) node[left,font=\fontsize{10}{12}\selectfont] {$y$};
\draw[dashed,line width=0.4pt] (-0.8,0.8)--(3.7,-3.7);
\draw[line width=0.8pt,domain=-1.8:1.8,samples=101,variable=\t] plot ({(\t*\t-\t)/sqrt(2)},{-(\t*\t+\t)/sqrt(2)});
\fill (0,0) circle (1.2pt);
\fill ({sqrt(2)},0) circle (1.2pt) node[above right,font=\fontsize{10}{12}\selectfont] {$(\sqrt2,0)$};
\fill (0,{-sqrt(2)}) circle (1.2pt) node[left,font=\fontsize{10}{12}\selectfont] {$(0,-\sqrt2)$};
\node[above left,font=\fontsize{10}{12}\selectfont] at (0,0) {$0$};
\node[rotate=-45,above,font=\fontsize{10}{12}\selectfont] at (2.7,-2.7) {$y=-x$};
\end{tikzpicture}

